def bfsdist(srcs):
    d={}; q=deque()
    for s in srcs: d[s]=0; q.append(s)
    while q:
        i,j=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<H and 0<=nj<W and (ni,nj) not in d:
